// ❌ OLD: Without keep-alive (Connection: close, or an Agent with
// keepAlive disabled), every request opens a NEW TCP connection: DNS
// (maybe), TCP handshake, and (for https) the TLS handshake — all
// before the request even starts. For N sequential small requests to
// the same host, that's N full handshakes: the dominant latency for
// request-heavy clients.
const http = require('node:http');

function fetchAll(ids) {
  // ❌ OLD: each get() may open a fresh connection
  for (const id of ids) {
    http.get(`http://api.example.com/items/${id}`, (res) => {
      // ...
    });
  }
}

// Default Agent: keepAlive disabled in older behavior → connections
// close after each response. Latency dominated by handshakes.

const http = require('node:http');

// ✅ NEW: keepAlive keeps free sockets in the Agent's pool so
// subsequent requests to the same host reuse the open connection — no
// repeated TCP/TLS handshakes.
const agent = new http.Agent({
  keepAlive: true, // ✅ NEW: reuse idle connections
  maxSockets: 10, // ✅ NEW: cap concurrent sockets per origin
  maxFreeSockets: 5, // ✅ NEW: keep a small pool of idle sockets
});

function fetchAll(ids) {
  for (const id of ids) {
    http.get({ hostname: 'api.example.com', path: `/items/${id}`, agent }, (res) => {
      // ✅ NEW: the Agent reuses pooled sockets
    });
  }
}

